	<div class="bpc-summary-totals">

		<div class="cart-subtotal  bpc-totals-row">
			<div class="bpc-totals-label"><?php esc_html_e('Subtotal', 'woocommerce'); ?></div>
			<div class="beton-checkout-subtotal bpc-totals-value"><?php wc_cart_totals_subtotal_html(); ?></div>
		</div>

		<?php foreach (WC()->cart->get_coupons() as $code => $coupon): ?>
			<div class="cart-discount coupon-<?php echo esc_attr(sanitize_title($code)); ?> bpc-totals-row">
				<div class="bpc-totals-label"><?php wc_cart_totals_coupon_label($coupon); ?></div>
				<div class="bpc-totals-value"><?php wc_cart_totals_coupon_html($coupon); ?></div>
			</div>
		<?php endforeach; ?>

		<?php if (WC()->cart->needs_shipping() && WC()->cart->show_shipping()): ?>

			<?php do_action('woocommerce_review_order_before_shipping'); ?>

			<?php //wc_cart_totals_shipping_html(); ?>

			<?php do_action('woocommerce_review_order_after_shipping'); ?>

		<?php endif; ?>

		<?php foreach (WC()->cart->get_fees() as $fee): ?>
			<div class="fee bpc-totals-row bpc-totals-row">
				<div class="bpc-totals-label"><?php echo esc_html($fee->name); ?></div>
				<div class="bpc-totals-value"><?php wc_cart_totals_fee_html($fee); ?></div>
			</div>
		<?php endforeach; ?>

		<?php if (wc_tax_enabled() && !WC()->cart->display_prices_including_tax()): ?>
			<?php if ('itemized' === get_option('woocommerce_tax_total_display')): ?>
				<?php foreach (WC()->cart->get_tax_totals() as $code => $tax): // phpcs:ignore WordPress.WP.GlobalVariablesOverride.Prohibited ?>
					<div class="tax-rate tax-rate-<?php echo esc_attr(sanitize_title($code)); ?> bpc-totals-row">
						<div class="bpc-totals-label"><?php echo esc_html($tax->label); ?></div>
						<div class="bpc-totals-value"><?php echo wp_kses_post($tax->formatted_amount); ?></div>
					</div>
				<?php endforeach; ?>
			<?php else: ?>
				<div class="tax-total bpc-totals-row">
					<div class="bpc-totals-label"><?php echo esc_html(WC()->countries->tax_or_vat()); ?></div>
					<div class="bpc-totals-value"><?php wc_cart_totals_taxes_total_html(); ?></div>
				</div>
			<?php endif; ?>
		<?php endif; ?>

		<div class="bpc-totals-divider"></div>
		<?php do_action('woocommerce_review_order_before_order_total'); ?>

		<div class="order-total bpc-totals-grand">
			<div class="bpc-totals-grand-label"><?php esc_html_e('Total', 'woocommerce'); ?></div>
			<div class="beton-checkout-total bpc-totals-grand-value"><?php wc_cart_totals_order_total_html(); ?></div>
		</div>

		<?php do_action('woocommerce_review_order_after_order_total'); ?>

	</div>

